mapper.select:
select
a.task_result_id,
a.task_id,
a.area_id,
a.c_type,
a.c_state,
a.modify_state,
a.task_count,
a.task_wait,
a.check_user,
a.check_date,
a.weather,
a.create_time,
a.execute_time,
a.task_code,
a.remark
from t_cruise_result a
where 1 = 1
 and a.task_result_id = #{taskResultId, jdbcType=VARCHAR}
 and a.task_id = #{taskId, jdbcType=VARCHAR}
 and a.area_id = #{areaId, jdbcType=VARCHAR}
 and a.c_type = #{cType, jdbcType=INTEGER}
 and a.c_state = #{cState, jdbcType=INTEGER}
 and a.modify_state = #{modifyState, jdbcType=INTEGER}
 and a.task_count = #{taskCount, jdbcType=INTEGER}
 and a.task_wait = #{taskWait, jdbcType=INTEGER}
 and a.check_user = #{checkUser, jdbcType=VARCHAR}
 and a.check_date = #{checkDate, jdbcType=TIMESTAMP}
 and a.weather = #{weather, jdbcType=VARCHAR}
 and a.create_time = #{createTime, jdbcType=TIMESTAMP}
 and a.execute_time = #{executeTime, jdbcType=TIMESTAMP}
 and a.task_code = #{taskCode, jdbcType=VARCHAR}
 and a.remark = #{remark, jdbcType=VARCHAR}

